"use strict";(self.webpackChunkswitches=self.webpackChunkswitches||[]).push([[501],{5763:o=>{o.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Intro","href":"/switch-configuration/docs/intro","docId":"intro","unlisted":false},{"type":"category","label":"Protocolos","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"LLDP","href":"/switch-configuration/docs/Protocolos/lldp","docId":"Protocolos/lldp","unlisted":false},{"type":"link","label":"LACP","href":"/switch-configuration/docs/Protocolos/lacp","docId":"Protocolos/lacp","unlisted":false},{"type":"link","label":"ICMP","href":"/switch-configuration/docs/Protocolos/icmp","docId":"Protocolos/icmp","unlisted":false},{"type":"link","label":"NTP","href":"/switch-configuration/docs/Protocolos/ntp","docId":"Protocolos/ntp","unlisted":false},{"type":"link","label":"SSH","href":"/switch-configuration/docs/Protocolos/ssh","docId":"Protocolos/ssh","unlisted":false},{"type":"link","label":"STP","href":"/switch-configuration/docs/Protocolos/stp","docId":"Protocolos/stp","unlisted":false},{"type":"link","label":"BPDU","href":"/switch-configuration/docs/Protocolos/bpdu","docId":"Protocolos/bpdu","unlisted":false},{"type":"link","label":"RPVST","href":"/switch-configuration/docs/Protocolos/rpvst","docId":"Protocolos/rpvst","unlisted":false},{"type":"link","label":"SNMP","href":"/switch-configuration/docs/Protocolos/snmp","docId":"Protocolos/snmp","unlisted":false}],"href":"/switch-configuration/docs/category/protocolos"},{"type":"category","label":"Comandos","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Seguridad y Acceso","href":"/switch-configuration/docs/Comandos/seguridad-y-acceso","docId":"Comandos/seguridad-y-acceso","unlisted":false},{"type":"link","label":"Red y Conectividad","href":"/switch-configuration/docs/Comandos/red-conectividad","docId":"Comandos/red-conectividad","unlisted":false},{"type":"link","label":"Rendimiento y Calidad de servicio","href":"/switch-configuration/docs/Comandos/rendimiento-calidad-servicio","docId":"Comandos/rendimiento-calidad-servicio","unlisted":false},{"type":"link","label":"Prevenci\xf3n de problemas","href":"/switch-configuration/docs/Comandos/prevencion-problemas","docId":"Comandos/prevencion-problemas","unlisted":false},{"type":"link","label":"Otros interesantes","href":"/switch-configuration/docs/Comandos/interesantes","docId":"Comandos/interesantes","unlisted":false}],"href":"/switch-configuration/docs/category/comandos"}]},"docs":{"Comandos/interesantes":{"id":"Comandos/interesantes","title":"Otros interesantes","description":"\u2705 `cli-session timeout 43200` -> Establece cuanto tiempo puede durar una sesi\xf3n CLI (12 horas).","sidebar":"tutorialSidebar"},"Comandos/prevencion-problemas":{"id":"Comandos/prevencion-problemas","title":"Prevenci\xf3n de problemas","description":"\u2705 `loop-protect` -> Detecta y mitiga bucles de red, que pueden colapsar el tr\xe1fico.","sidebar":"tutorialSidebar"},"Comandos/red-conectividad":{"id":"Comandos/red-conectividad","title":"Red y Conectividad","description":"\u2705 `lldp` -> Habilita LLDP (Link Layer Discovery Protocol), que permite descubrir qu\xe9 otros dispositivos est\xe1n conectados (\xfatil para gestionar la red).","sidebar":"tutorialSidebar"},"Comandos/rendimiento-calidad-servicio":{"id":"Comandos/rendimiento-calidad-servicio","title":"Rendimiento y Calidad de servicio","description":"\u2705 `qos queue-profile` + `schedule-profile`  -> Configura la Calidad de Servicio (QoS): garantiza ancho de banda para tr\xe1fico sensible como voz (VoIP).","sidebar":"tutorialSidebar"},"Comandos/seguridad-y-acceso":{"id":"Comandos/seguridad-y-acceso","title":"Seguridad y Acceso","description":"\u2705 `banner motd` -> Muestra un mensaje de advertencia cuando alguien accede al switch. Es importante legalmente para avisar que es un sistema privado.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Intro","description":"La siguiente documentaci\xf3n, recopila y resume conceptos relacionados con la configuraci\xf3n de switches, como protocolos y comandos.","sidebar":"tutorialSidebar"},"Protocolos/bpdu":{"id":"Protocolos/bpdu","title":"BPDU","description":"\u2705 BPDU (Bridge Protocol Data Unit) es un tipo de mensaje utilizado por el protocolo STP (Spanning Tree Protocol), que opera en la capa 2 (enlace de datos). Su funci\xf3n es intercambiar informaci\xf3n entre switches para evitar bucles en la red Ethernet.","sidebar":"tutorialSidebar"},"Protocolos/icmp":{"id":"Protocolos/icmp","title":"ICMP","description":"\u2705 ICMP (Internet Control Message Protocol) es un protocolo de la capa de red (capa 3) definido en el est\xe1ndar RFC 792. Su funci\xf3n principal es enviar mensajes de control y diagn\xf3stico entre dispositivos de red para reportar errores o informar sobre el estado de la comunicaci\xf3n IP.","sidebar":"tutorialSidebar"},"Protocolos/lacp":{"id":"Protocolos/lacp","title":"LACP","description":"\u2705 LACP (Link Aggregation Control Protocol) es un protocolo de la capa 2 (enlace de datos), definido por el est\xe1ndar IEEE 802.3ad (ahora parte de 802.1AX). Su objetivo principal es agrupar varios enlaces f\xedsicos (cables de red) en un \xfanico enlace l\xf3gico para aumentar el ancho de banda y mejorar la redundancia.","sidebar":"tutorialSidebar"},"Protocolos/lldp":{"id":"Protocolos/lldp","title":"LLDP","description":"\u2705 LLDP (Link Layer Discovery Protocol) es un protocolo de descubrimiento de capa 2 (enlace de datos) definido por el est\xe1ndar IEEE 802.1AB. Su funci\xf3n principal es permitir que los dispositivos de red (como switches, routers, puntos de acceso, etc.) anuncien su identidad y capacidades a los dispositivos directamente conectados.","sidebar":"tutorialSidebar"},"Protocolos/ntp":{"id":"Protocolos/ntp","title":"NTP","description":"\u2705 NTP (Network Time Protocol) es un protocolo de capa de aplicaci\xf3n dise\xf1ado para sincronizar los relojes de los dispositivos de una red con una fuente de tiempo precisa. Est\xe1 definido en RFC 5905.","sidebar":"tutorialSidebar"},"Protocolos/rpvst":{"id":"Protocolos/rpvst","title":"RPVST","description":"\u2705 RPVST (Rapid Per-VLAN Spanning Tree) es una mejora del protocolo RSTP (Rapid Spanning Tree Protocol), que es una versi\xf3n m\xe1s r\xe1pida y eficiente del cl\xe1sico STP (Spanning Tree Protocol). RPVST trabaja espec\xedficamente con VLANs (redes de \xe1rea local virtuales), lo que le permite proporcionar un \xe1rbol de expansi\xf3n independiente por cada VLAN.","sidebar":"tutorialSidebar"},"Protocolos/snmp":{"id":"Protocolos/snmp","title":"SNMP","description":"\u2705 SNMP (Simple Network Management Protocol) es un protocolo de gesti\xf3n de redes utilizado para supervisar y administrar dispositivos de red como routers, switches, servidores, impresoras y otros dispositivos compatibles. SNMP permite que un sistema de gesti\xf3n de red recoja informaci\xf3n de estos dispositivos, los configure y supervisione su estado.","sidebar":"tutorialSidebar"},"Protocolos/ssh":{"id":"Protocolos/ssh","title":"SSH","description":"\u2705 SSH (Secure Shell) es un protocolo de red de capa de aplicaci\xf3n que permite conectarse de forma segura a otro dispositivo a trav\xe9s de una red insegura (como Internet). Est\xe1 definido en RFC 4251.","sidebar":"tutorialSidebar"},"Protocolos/stp":{"id":"Protocolos/stp","title":"STP","description":"\u2705 STP (Spanning Tree Protocol) es un protocolo de capa 2 (enlace de datos), definido por IEEE 802.1D, cuyo objetivo principal es evitar bucles de red en redes conmutadas (switching).","sidebar":"tutorialSidebar"}}}}')}}]);